z = 3.0 * h1/abs(uv1.y);
rs.x = uv1.x * z;
rs.y = z + q30;
noise = texture(sampler_pw_noise_lq,rs / 32.0);
noise *= (noise >= .9);
if (noise.x+noise.y+noise.z > .01) noise += (noise2)*.8;
ret1 += noise;
z = h1/abs(uv1.x);
rs.y = uv1.y * z;
rs.x = z + q30;
noise = texture(sampler_pw_noise_lq,rs / 32.0);
noise *= (noise >= .9);
noise *= 1+.5*(lum(texture(sampler_noise_hq,16.0 * rs))-.5);
if (noise.x+noise.y+noise.z > .01) noise += (noise2)*.8;
ret1 += noise;
z = 3.0 * h1/abs(uv1.x);
rs.y = uv1.y * z;
rs.x = z + q30;
noise = texture(sampler_pw_noise_lq,rs / 32.0);
noise *= (noise >= .9);
if (noise.x+noise.y+noise.z > .01) noise += (noise2)*.8;
