uv = 0.5 + (0.5 - abs( fract( bipolar_uv * 0.5 ) * 2.0 - 1.0 ));
vec2 uvo = uv;
uv = (uv-0.5);
factorA = uv+ vec2(q1,q2);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv1 = product;
factorA = uv+ vec2(q3,q4);
factorB = vec2( 8.0 , 0.0 );
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
vec2 uv2 = product;
factorA = uv+ vec2(q5,q6);
